#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <d3d9.h>
#include <cstdio>
#include <initializer_list>
#include <stdexcept>
#include "texture_creation.h"

void require(bool condition, const char* message) {
  if (!condition) { throw std::runtime_error(message); }
}

struct Statistics {
  unsigned live = 0;
  unsigned releases = 0;
  unsigned cancellations = 0;
  unsigned destroyMessages = 0;
};

struct Interface {};
class Texture : public Interface {
  Statistics& m_statistics;
  bool m_serverCreated = true;
  Interface** m_output;
  bool m_requireNull;

public:
  Texture(Statistics& statistics, Interface** output, bool requireNull)
    : m_statistics(statistics), m_output(output), m_requireNull(requireNull) {
    ++m_statistics.live;
  }
  void cancelServerCreation() {
    ++m_statistics.cancellations;
    m_serverCreated = false;
  }
  ULONG Release() {
    require(!m_requireNull || !*m_output, "failed output must be null before releasing wrapper");
    ++m_statistics.releases;
    if (m_serverCreated) { ++m_statistics.destroyMessages; }
    delete this;
    return 0;
  }
  ~Texture() { --m_statistics.live; }
};

int main() {
  try {
    Statistics rejected;
    // Exercise repeated backend invalid-call and allocation failures, followed by reuse.
    for (unsigned i = 0; i < 10000; ++i) {
      Interface* output = nullptr;
      auto* texture = new Texture(rejected, &output, true);
      output = texture;
      const auto error = (i & 1) ? D3DERR_INVALIDCALL : D3DERR_OUTOFVIDEOMEMORY;
      require(l4d2_texture::completeCreation(texture, &output, { error, true }) == error,
        "backend HRESULT changed");
      require(!output && !rejected.live && rejected.destroyMessages == 0,
        "failed resource was retained or sent a spurious server Destroy");
    }
    require(rejected.releases == 10000 && rejected.cancellations == 10000,
      "failed wrappers were not released exactly once");

    Statistics timeout;
    Interface* output = nullptr;
    auto* texture = new Texture(timeout, &output, true);
    output = texture;
    require(l4d2_texture::completeCreation(texture, &output, { D3DERR_INVALIDCALL, false }) == D3DERR_INVALIDCALL,
      "timeout result changed");
    require(!output && !timeout.live && !timeout.cancellations && timeout.destroyMessages == 1,
      "unresolved creation did not preserve ordered server cleanup");

    for (const bool responded : { true, false }) {
      Statistics success;
      output = nullptr;
      texture = new Texture(success, &output, false);
      output = texture;
      require(l4d2_texture::completeCreation(texture, &output, { D3D_OK, responded }) == D3D_OK,
        "success changed");
      require(output == texture && success.live == 1 && !success.releases && !success.cancellations,
        "successful output lost ownership");
      texture->Release();
      require(!success.live && success.destroyMessages == 1, "successful resource cleanup changed");
    }
    std::puts("PASS: 10000 failed texture creations release wrappers, preserve backend HRESULT and null output; explicit failures suppress nonexistent server Destroy; timeouts retain ordered cleanup; successful sync/async creation keeps ownership (mock wrapper).");
    return 0;
  } catch (const std::exception& error) {
    std::fprintf(stderr, "%s\n", error.what());
    return 1;
  }
}
